"use strict";

// Camera+ — a separate camera object for scenes, with depth of field, vibrate,
// and focus tools. The CM3 camera and its rendering are left untouched.
//
// Object type zoidium:camera-plus/camera ("Camera+") is registered through the
// Zoidium 3D object registry and appears under Camera in the 3D picker.
//
// Selection rule: a Scene renders through the first active Camera+ among its
// child objects, in depth-first list order. When a scene has none, its pass keeps
// the CM3 camera exactly as CM3 set it. With no Camera+ in a project, the
// hooks below change nothing that CM3 computes.
//
// Hooks, each installed only while the plugin is enabled and each undone on
// disable (only when the host still references the replacement):
// - THREE.RenderPass.prototype.render: delegates to the original unless the
//   scene's Camera+ enabled depth of field on this pass.
// - PZ.layer.scene.prototype.update / unload: sync the pass camera and the
//   depth-of-field state after CM3's own update.
// - Shared-camera layer registration and deterministic second-pass tracking.
// - PZ.expression.methods.focusDistanceTo: the focus link expression method.
// - Property control "camera-plus/focus-tools": the focus button row.
//
// Sources in ./plugins/camera-plus/*.js are evaluated through the bundle asset
// resolver and publish their parts on a shared `parts` object.

const PART_FILES = ["vibrate.js", "scene-dof.js", "scene-motion-blur.js", "camera-class.js", "focus-ui.js", "shared-depth.js", "shared-camera.js"];
const LEGACY_LAYER_TYPE = 9;
const CAMERA_OBJECT_TYPE_NUMBER = 6;
const REPORT_PREFIX = "Camera+:";

let active = null;
let hooks = null;

function loadParts(getAsset, PZ, THREE) {
  if (typeof getAsset !== "function") {
    throw new Error("Camera+ needs the plugin bundle asset resolver.");
  }
  const parts = {};
  for (const file of PART_FILES) {
    const source = getAsset("text", "./plugins/camera-plus/" + file);
    if (typeof source !== "string") {
      throw new Error("Camera+ is missing its bundled source: " + file);
    }
    // Parameters (not bare eval) keep the parts isolated from module scope.
    new Function("PZ", "THREE", "parts", source)(PZ, THREE, parts);
  }
  return parts;
}

function createTeardown() {
  const undo = [];
  let finished = false;
  return {
    push(step) {
      undo.push(step);
    },
    run() {
      if (finished) return;
      finished = true;
      for (const step of undo.splice(0).reverse()) {
        try {
          step();
        } catch (error) {
          console.error(REPORT_PREFIX, "cleanup step failed", error);
        }
      }
    },
  };
}

// Replace a method only while it is reachable; undo restores the original
// only if the host still references this replacement.
function patchMethod(holder, key, replacement, teardown) {
  const original = holder[key];
  holder[key] = replacement;
  teardown.push(function () {
    if (holder[key] === replacement) holder[key] = original;
  });
}

function requireMember(value, label) {
  if (value === undefined || value === null) {
    throw new Error("Camera+ needs " + label + " from the CM3 runtime.");
  }
  return value;
}

function requireMethod(holder, key, label) {
  if (!holder || typeof holder[key] !== "function") {
    throw new Error("Camera+ needs " + label + " from the CM3 runtime.");
  }
  return holder[key];
}

function activateCameraPlus(context, teardown) {
  const PZ = requireMember(context.PZ || globalThis.PZ, "PZ");
  const THREE = requireMember((context.window && context.window.THREE) || globalThis.THREE, "THREE");
  const object3d = context.object3d;
  const apis = context.apis;
  const ZoidiumUI = (context.window && context.window.ZoidiumUI) || globalThis.ZoidiumUI || null;

  if (!object3d || typeof object3d.registerClass !== "function") {
    throw new Error("Camera+ needs the Zoidium 3D object registry.");
  }
  if (!apis || !apis.propertyControls || typeof apis.propertyControls.register !== "function") {
    throw new Error("Camera+ needs ZoidiumPluginApis.propertyControls.");
  }
  if (!ZoidiumUI || !ZoidiumUI.controls) {
    throw new Error("Camera+ needs ZoidiumUI.");
  }
  requireMethod(apis.timeline, "registerTrackButton", "ZoidiumPluginApis.timeline.registerTrackButton");
  requireMethod(apis.timeline, "registerTrackField", "ZoidiumPluginApis.timeline.registerTrackField");
  requireMethod(apis.media, "registerPreset", "ZoidiumPluginApis.media.registerPreset");
  requireMethod(apis.layers, "registerType", "ZoidiumPluginApis.layers.registerType");
  requireMethod(PZ.layer && PZ.layer.scene && PZ.layer.scene.prototype, "update", "PZ.layer.scene.prototype.update");
  requireMethod(PZ.layer && PZ.layer.scene && PZ.layer.scene.prototype, "unload", "PZ.layer.scene.prototype.unload");
  requireMethod(PZ.layer, "create", "PZ.layer.create");
  requireMethod(THREE.RenderPass && THREE.RenderPass.prototype, "render", "THREE.RenderPass.prototype.render");
  requireMember(PZ.expression && PZ.expression.methods, "PZ.expression.methods");
  requireMember(PZ.ui && PZ.ui.properties, "PZ.ui.properties");
  requireMember(PZ.object3d && PZ.object3d.camera, "PZ.object3d.camera");

  const parts = loadParts(context.getAsset, PZ, THREE);
  const camera = parts.camera;
  const focus = parts.focus;
  const SceneDof = parts.dof.createSceneDofClass(THREE);
  const SceneMotionBlur = parts.motion.createSceneMotionBlurClass(THREE);
  const CameraPlus = camera.createClass(PZ, THREE, parts.vibrate);
  const worldDistance = camera.worldDistance;

  let live = true;
  let focusWindowKey = 0;
  const scenes = new Map(); // scene -> { previousCamera, dof }
  let reported = false;

  function getEditor() {
    return globalThis.CM || context.editor || null;
  }

  function currentProject() {
    const editor = getEditor();
    return editor && editor.project ? editor.project : null;
  }

  // ---- scene selection and depth of field ---------------------------------

  function isCameraPlusObject(object) {
    return !!object && object.type === camera.OBJECT_TYPE && !object._zoidiumMissingObject;
  }

  function findActiveCamera(scene, time) {
    function walk(objects) {
      for (const object of objects || []) {
        if (object.properties?.enabled && object.properties.enabled.get(time) !== 1) continue;
        if (isCameraPlusObject(object) && object.threeObj && object.isActive()) return object;
        // Repeater clones do not represent a single authored camera pose.
        if (object.__zoidiumRepeater) continue;
        const child = object.objects && walk(object.objects);
        if (child) return child;
      }
      return null;
    }
    return walk(scene.objects);
  }

  // Preserve the exact native camera the Scene used before borrowing one.
  // If it was removed, use the last authored native camera as CM3 load does.
  function nativeCameraObjectOf(scene, preferred) {
    const cameras = [];
    function walk(objects) {
      for (const object of objects || []) {
        if (!object || object._zoidiumMissingObject || object.__zoidiumRepeater) continue;
        if (!isCameraPlusObject(object) && (object instanceof PZ.object3d.camera || object.type === CAMERA_OBJECT_TYPE_NUMBER) && object.threeObj) cameras.push(object);
        if (object.objects) walk(object.objects);
      }
    }
    walk(scene.objects);
    const previous = preferred || scenes.get(scene)?.previousCamera || scene.pass?.camera;
    return cameras.find(object => object.threeObj === previous) || cameras[cameras.length - 1] || null;
  }

  function restoreScene(scene, entry) {
    const pass = scene.pass;
    if (pass) {
      pass.__cameraPlusDof = null;
      pass.__cameraPlusState = null;
      const own = nativeCameraObjectOf(scene, entry.previousCamera)?.threeObj;
      pass.camera = own || entry.previousCamera || pass.camera;
    }
    if (entry.blur) { entry.blur.unload(); entry.blur = null; }
    if (entry.dof) {
      entry.dof.unload();
      entry.dof = null;
    }
  }

  function syncScene(scene, time, sharedCamera, master) {
    const pass = scene.pass;
    if (!pass) return;
    let entry = scenes.get(scene) || null;
    const cameraObject = sharedCamera || (entry && entry.sampling ? entry.cameraObject : findActiveCamera(scene, time));
    if (!cameraObject) {
      if (entry) {
        restoreScene(scene, entry);
        scenes.delete(scene);
      }
      return;
    }
    if (!entry) {
      entry = { previousCamera: pass.camera, dof: null, blur: null, scene };
      scenes.set(scene, entry);
    }
    pass.camera = cameraObject.threeObj;
    entry.cameraObject = cameraObject;
    if (!entry.sampling) {
      entry.time = time;
      entry.motion = cameraObject.readMotionBlur?.(master ? master.local : time) || null;
      entry.master = master;
    }
    if (entry.motion && !entry.blur) entry.blur = new SceneMotionBlur();
    pass.__cameraPlusState = entry;
    const cameraTime = master ? master.local : entry.sampling && entry.master ? entry.master.local + time - entry.time : time;
    const settings = cameraObject.readDepthOfField?.(cameraTime);
    if (settings) {
      if (!entry.dof) entry.dof = new SceneDof();
      entry.dof.configure(settings);
      entry.dof.enabled = true;
      pass.__cameraPlusDof = entry.dof;
    } else {
      if (entry.dof) entry.dof.enabled = false;
      pass.__cameraPlusDof = null;
    }
  }

  function reportOnce(error) {
    if (reported) return;
    reported = true;
    console.error(REPORT_PREFIX, "scene camera sync failed; the scene keeps its CM3 camera", error);
  }

  function restoreAllScenes() {
    for (const [scene, entry] of Array.from(scenes.entries())) {
      restoreScene(scene, entry);
    }
    scenes.clear();
  }

  teardown.push(function () {
    live = false;
  });
  teardown.push(restoreAllScenes);

  // ---- object class ------------------------------------------------------

  const unregisterClass = object3d.registerClass({
    type: camera.OBJECT_TYPE,
    schemaVersion: camera.SCHEMA_VERSION,
    name: "Camera+",
    factory: () => new CameraPlus(),
  });
  teardown.push(function () {
    unregisterClass();
  });

  // ---- render pass depth of field -----------------------------------------

  const renderPassProto = THREE.RenderPass.prototype;
  const originalRender = renderPassProto.render;
  patchMethod(renderPassProto, "render", function renderWithCameraPlus(renderer, target, readTarget, forceClear) {
    const state = this.__cameraPlusState;
    const pass = this;
    function draw(output, clear) {
      const dof = pass.__cameraPlusDof;
      if (!live || !dof || !dof.enabled || pass.__cameraPlusGlobalDof) {
        return originalRender.call(pass, renderer, output, readTarget, clear);
      }
      const previous = pass.scene.overrideMaterial;
      try {
        pass.scene.overrideMaterial = pass.overrideMaterial;
        pass.envMap.render(renderer);
        pass.motionBlur.render(renderer);
        dof.render(renderer, output, pass.scene, pass.camera, output.viewport, clear);
      } finally {
        pass.scene.overrideMaterial = previous;
      }
    }
    if (live && state && state.motion && !state.sampling) {
      state.sampling = true;
      try {
        return state.blur.render(renderer, target, state.time, state.motion,
          (frame) => {
            if (state.master) {
              const masterTime = state.master.local + frame - state.time;
              state.master.layer.update(masterTime);
            }
            state.scene.update(frame);
          }, draw, forceClear);
      } finally {
        state.sampling = false;
      }
    }
    return draw(target, forceClear);
  }, teardown);

  // ---- scene update and unload ---------------------------------------------

  const sceneProto = PZ.layer.scene.prototype;
  const originalSceneUpdate = sceneProto.update;
  patchMethod(sceneProto, "update", function updateWithCameraPlus(time) {
    // CM3 captures future model-view matrices before updating the output
    // frame. With Camera+, compute that future camera view explicitly; the
    // camera inverse left by the previous render is not a valid sample.
    if (live && this.motionBlur?.velocityBuffer) {
      const entry = scenes.get(this);
      const sampledCamera = entry?.sampling ? entry.cameraObject : shared.cameraFor(this, time + .5) || findActiveCamera(this, time);
      if (sampledCamera) {
        for (const object of this.objects) object.update(time + 0.5);
        this.threeObj.updateMatrixWorld(true);
        sampledCamera.threeObj.matrixWorldInverse.getInverse(sampledCamera.threeObj.matrixWorld);
        this.pass.camera = sampledCamera.threeObj;
      }
    }
    const out = originalSceneUpdate.apply(this, arguments);
    if (live) {
      try {
        syncScene(this, time);
      } catch (error) {
        reportOnce(error);
      }
    }
    return out;
  }, teardown);

  const originalSceneUnload = sceneProto.unload;
  patchMethod(sceneProto, "unload", function unloadWithCameraPlus() {
    if (live) {
      const entry = scenes.get(this);
      if (entry) {
        restoreScene(this, entry);
        scenes.delete(this);
      }
    }
    return originalSceneUnload.apply(this, arguments);
  }, teardown);

  // ---- legacy Davidium Camera layers ----------------------------------------

  function migrateCameraData(data) {
    if (!data || typeof data !== "object") return data;
    if (data.type === 6 && Object.keys(data.properties || {}).some(key => /^(dof|vibrate|focalLength|filmGate|zoom|filmOffset|projection)/.test(key))) {
      const properties = Object.assign({}, data.properties);
      const depthOfField = Object.assign({}, properties.depthOfField);
      for (const [oldKey, newKey] of Object.entries({
        dof: "enabled", dofFocusDistance: "focusDistance", dofAperture: "aperture",
        dofFocusAreaWidth: "focusAreaWidth", dofNearBlurLevel: "nearBlurLevel", dofFarBlurLevel: "farBlurLevel",
      })) {
        if (properties[oldKey] !== undefined) depthOfField[newKey] = properties[oldKey];
      }
      properties.depthOfField = depthOfField;
      properties.projection = data.objectType === 2 ? "orthographic" : "perspective";
      return { type: camera.OBJECT_TYPE, schemaVersion: camera.SCHEMA_VERSION, properties };
    }
    return Object.assign({}, data, data.objects ? { objects: data.objects.map(migrateCameraData) } : {});
  }

  const shared = parts.shared({ PZ, THREE, apis, teardown, patchMethod,
    migrateCameraData, syncScene, findActiveCamera, nativeCameraObjectOf, plugin: context.plugin, getProject: currentProject });
  const projectChanged = getEditor()?.onProjectChanged;
  if (projectChanged?.watch && projectChanged?.unwatch) {
    let previousProject = currentProject();
    const onProjectChanged = () => {
      const next = currentProject();
      if (previousProject && previousProject !== next) previousProject.forEachItemOfType(PZ.object3d, object => {
        if (isCameraPlusObject(object)) object.unload();
      });
      previousProject = next;
      restoreAllScenes();
      shared.projectChanged();
    };
    teardown.push(() => projectChanged.unwatch(onProjectChanged));
    projectChanged.watch(onProjectChanged);
  }

  // ---- focus tools ---------------------------------------------------------

  const focusOptions = {
    PZ: PZ,
    THREE: THREE,
    ui: context.ui,
    getEditor: getEditor,
    objectType: camera.OBJECT_TYPE,
    worldDistance: worldDistance,
    nextKey: function () {
      focusWindowKey += 1;
      return focusWindowKey;
    },
  };
  const openFocusTools = function (owner) {
    return focus.createFocusTools(focusOptions, owner).openWindow();
  };

  const expressionMethod = focus.createExpressionMethod({
    THREE: THREE,
    getEditor: getEditor,
    worldDistance: worldDistance,
  });
  expressionMethod.__cameraPlus = true;
  const methods = PZ.expression.methods;
  if (typeof methods[focus.METHOD_NAME] === "function" && !methods[focus.METHOD_NAME].__cameraPlus) {
    throw new Error("Camera+ cannot define " + focus.METHOD_NAME + ": the name is already in use.");
  }
  methods[focus.METHOD_NAME] = expressionMethod;
  teardown.push(function () {
    if (methods[focus.METHOD_NAME] === expressionMethod) delete methods[focus.METHOD_NAME];
  });

  const unregisterControl = apis.propertyControls.register(camera.FOCUS_CONTROL_ID, {
    type: PZ.property.type.TEXT,
    create: function (property, controlContext) {
      return focus.createControl({ PZ: PZ, zoidiumUI: ZoidiumUI, openFor: openFocusTools }, property, controlContext);
    },
  });
  teardown.push(function () {
    unregisterControl();
  });

  hooks = {
    legacyLayersPresent() {
      const project = currentProject();
      if (!project || typeof project.forEachItemOfType !== "function") return false;
      let found = false;
      project.forEachItemOfType(PZ.layer, function (layer) {
        if (layer.type === LEGACY_LAYER_TYPE || layer.__cameraPlusLegacy) found = true;
      });
      return found || !!project.sequence?.videoTracks?.some(track => track.track3d);
    },
  };
  teardown.push(function () {
    hooks = null;
  });
}

module.exports = {
  activate(context) {
    if (active) return;
    const teardown = createTeardown();
    if (context && context.lifecycle && typeof context.lifecycle.onDispose === "function") {
      context.lifecycle.onDispose(function () {
        teardown.run();
      });
    }
    try {
      activateCameraPlus(context, teardown);
    } catch (error) {
      teardown.run();
      throw error;
    }
    active = teardown;
  },
  deactivate() {
    const current = active;
    active = null;
    if (current) current.run();
  },
  isInUse() {
    return hooks ? hooks.legacyLayersPresent() : false;
  },
};

text./plugins/camera-plus/focus-ui.js:
// Camera+ focus tools: a property-row button in the Depth of Field group opens
// a floating window that picks a target object in the same scene. The window
// links the focus distance to that object (live expression) or sets it once
// at the playhead as a keyframe. Edits go through the CM3 property operations
// and history, so undo/redo works.
//
// CM3 expressions cannot name the owning object, so a link stores both object
// addresses as literal arrays: focusDistanceTo([camera], [target]).
//
// Evaluated with (PZ, THREE, parts) by camera-runtime.js; publishes parts.focus.
parts.focus = (function () {
  const METHOD_NAME = "focusDistanceTo";
  const WINDOW_PREFIX = "focus:";

  function ownerObject(PZ, property) {
    let node = property;
    for (let depth = 0; node && depth < 16; depth++) {
      if (node instanceof PZ.object3d) return node;
      node = node.parent;
    }
    return null;
  }

  function resolveEditor(getEditor) {
    try {
      return (getEditor && getEditor()) || null;
    } catch (_error) {
      return null;
    }
  }

  // options: PZ, THREE, ui (context.ui), getEditor, objectType (Camera+ type id),
  // worldDistance(THREE, from, to).
  function createFocusTools(options, camera) {
    const PZ = options.PZ;
    const THREE = options.THREE;
    const ui = options.ui;
    const focusProperty = camera.properties.depthOfField.focusDistance;

    function notify(message) {
      try {
        if (ui && typeof ui.notify === "function") ui.notify({ title: "Focus Tools", message: message });
      } catch (_error) { /* notification is best-effort */ }
    }

    // Targets are limited to the camera's scene. Their transforms are updated
    // in the same scene pass as the camera, so a link reads current values.
    function listTargets() {
      const scene = camera.tryGetParentOfType(PZ.layer);
      const items = [];
      const byId = new Map();
      if (!scene) return { items: items, byId: byId };
      scene.forEachItemOfType(PZ.object3d, function (object) {
        if (object === camera || !object.threeObj || object._zoidiumMissingObject) return;
        if (object instanceof PZ.object3d.camera || object.type === options.objectType) return;
        const id = JSON.stringify(object.getAddress());
        let name = "3D Object";
        try {
          name = object.properties.name.get() || name;
        } catch (_error) { /* keep fallback */ }
        items.push({ id: id, title: name, detail: scene.properties.name.get() || "" });
        byId.set(id, object);
      });
      return { items: items, byId: byId };
    }

    // Every button is one history operation, so it undoes in a single step.
    function edit(label, run) {
      const editor = resolveEditor(options.getEditor);
      if (!editor || !editor.history || !editor.project || !editor.playback) {
        notify("No active editor to " + label + ".");
        return;
      }
      const ops = new PZ.ui.properties(editor);
      editor.history.startOperation();
      try {
        run(editor, ops);
      } catch (error) {
        console.error("Camera+ focus tools could not " + label + ".", error);
        notify("Could not " + label + ".");
      } finally {
        editor.history.finishOperation();
      }
    }

    function clearExpression(ops) {
      if (focusProperty.expression) {
        ops.setExpression({ property: focusProperty.getAddress(), expression: null });
      }
    }

    function link(target) {
      edit("link the focus distance", function (editor, ops) {
        const source = METHOD_NAME + "(" + JSON.stringify(camera.getAddress()) + ", " +
          JSON.stringify(target.getAddress()) + ")";
        ops.setExpression({ property: focusProperty.getAddress(), expression: source });
      });
    }

    function setOnce(target) {
      edit("set the focus distance", function (editor, ops) {
        const distance = options.worldDistance(THREE, camera, target);
        clearExpression(ops);
        const frame = editor.playback.currentFrame - focusProperty.frameOffset;
        ops.setValue({ property: focusProperty.getAddress(), frame: frame, value: distance });
      });
    }

    // Unlink always clears the expression, even when none is read back.
    function unlink() {
      edit("unlink the focus distance", function (editor, ops) {
        ops.setExpression({ property: focusProperty.getAddress(), expression: null });
      });
    }

    function openWindow() {
      if (!ui || typeof ui.openWindow !== "function") {
        notify("The floating window API is unavailable.");
        return null;
      }
      if (!camera._focusWindowKey) camera._focusWindowKey = options.nextKey();
      let selectedId = null;
      let current = listTargets();
      function selectedObject() {
        return selectedId !== null ? current.byId.get(selectedId) || null : null;
      }
      const controls = ui.controls;
      return ui.openWindow({
        id: WINDOW_PREFIX + camera._focusWindowKey,
        title: "Focus Tools",
        subtitle: camera.properties.name.get(),
        persistKey: "focus-tools",
        width: 320,
        height: 380,
        mount(body) {
          const section = controls.section("Target object");
          const picker = controls.list({
            items: current.items,
            emptyText: "No other 3D objects in this scene.",
            onSelect(id) {
              selectedId = id;
            },
          });
          section.body.appendChild(picker.element);
          body.appendChild(section.element);
          body.appendChild(controls.note(
            "Link keeps the focus distance following the target. Set Once writes the current distance at the playhead.",
          ).element);
          // The list is captured when the window opens, but objects can be
          // added or removed while it stays open (reopening the same id only
          // focuses the window). Refresh on every scene-object change and on
          // every validity poll so the list never goes stale.
          function refresh() {
            const fresh = listTargets();
            current = fresh;
            if (picker && typeof picker.setItems === "function") picker.setItems(fresh.items);
            if (selectedId !== null && !fresh.byId.has(selectedId)) {
              selectedId = null;
              if (picker && typeof picker.set === "function") picker.set(null);
            }
          }
          let unwatch = null;
          try {
            const scene = camera.tryGetParentOfType(PZ.layer);
            const list = scene && scene.objects;
            if (list && list.onListChanged && typeof list.onListChanged.watch === "function") {
              const onChange = function () {
                refresh();
              };
              list.onListChanged.watch(onChange);
              unwatch = function () {
                if (typeof list.onListChanged.unwatch === "function") list.onListChanged.unwatch(onChange);
              };
            }
          } catch (_error) {
            unwatch = null;
          }
          camera._focusRefreshTargets = refresh;
          return function cleanup() {
            selectedId = null;
            if (camera._focusRefreshTargets === refresh) camera._focusRefreshTargets = null;
            if (unwatch) unwatch();
          };
        },
        isValid: () => {
          if (typeof camera._focusRefreshTargets === "function") {
            try {
              camera._focusRefreshTargets();
            } catch (_error) { /* a stale list is better than a closed window */ }
          }
          return camera.parent != null;
        },
        footer: [
          {
            title: "Link",
            variant: "primary",
            onClick: () => {
              const target = selectedObject();
              if (target) link(target);
              else notify("Select a target object first.");
            },
          },
          {
            title: "Set Once",
            onClick: () => {
              const target = selectedObject();
              if (target) setOnce(target);
              else notify("Select a target object first.");
            },
          },
          { title: "Unlink", onClick: () => unlink() },
        ],
      });
    }

    return { openWindow: openWindow, listTargets: listTargets };
  }

  // Property-row control factory for the focus entry in the Depth of Field
  // group. `zoidiumUI` supplies the shared button builder; `openFor(object)`
  // opens the window for the owning camera.
  function createControl(options, property, context) {
    const owner = ownerObject(options.PZ, property);
    const document = context && context.document;
    if (!owner || !document || !options.zoidiumUI) return null;
    const row = options.zoidiumUI.controls.buttonRow([
      {
        title: "Focus Tools...",
        hint: "Link or set the focus distance to another object in this scene",
        onClick: function () {
          options.openFor(owner);
        },
      },
    ]);
    const wrap = document.createElement("div");
    wrap.className = "editbox zoidium-camera-focus-tools";
    wrap.appendChild(row.element);
    return wrap;
  }

  // Expression method. Arguments are object addresses in the active project;
  // the result is the world distance between the two current transforms.
  function createExpressionMethod(options) {
    return function focusDistanceTo(cameraAddress, targetAddress) {
      const editor = resolveEditor(options.getEditor);
      const project = editor && editor.project;
      if (!project || typeof project.addressLookup !== "function") return 0;
      const from = project.addressLookup(cameraAddress);
      const to = project.addressLookup(targetAddress);
      if (!from || !from.threeObj || !to || !to.threeObj) return 0;
      return options.worldDistance(options.THREE, from, to);
    };
  }

  return {
    METHOD_NAME: METHOD_NAME,
    createFocusTools: createFocusTools,
    createControl: createControl,
    createExpressionMethod: createExpressionMethod,
  };
})();

text./plugins/camera-plus/scene-dof.js:
// Camera+ depth of field: a per-scene post pass over the active camera.
//
// The scene is rendered twice into offscreen targets (color, then packed
// depth). A single full-screen pass then gathers a deterministic golden-angle
// disc of samples whose radius follows the distance from the focus plane.
// Samples are averaged with their own alpha, so out-of-focus foregrounds
// spread over the background instead of keeping hard edges. In-focus pixels
// (sub-pixel radius) pass through untouched. The output depends only on the
// current scene render and the configured uniforms, so it is a pure function
// of the project state at time t.
//
// Evaluated with (PZ, THREE, parts) by camera-runtime.js; publishes parts.dof.
parts.dof = (function () {
  const VERTEX_SHADER = [
    "uniform vec2 uvScale;",
    "varying vec2 vUv;",
    "varying vec2 vUvScaled;",
    "void main() {",
    "    vUv = uv;",
    "    vUvScaled = uv * uvScale;",
    "    gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );",
    "}",
  ].join("\n");

  const FRAGMENT_SHADER = [
    "uniform sampler2D tColor;",
    "uniform sampler2D tDepth;",
    "uniform vec2 resolution;",
    "uniform float orthographic;",
    "uniform float near;",
    "uniform float far;",
    "uniform float aperture;",
    "uniform float focusDistance;",
    "uniform float focusAreaWidth;",
    "uniform float nearBlurLevel;",
    "uniform float farBlurLevel;",
    "varying vec2 vUvScaled;",
    "const float UnpackDownscale = 255. / 256.;",
    "const vec3 PackFactors = vec3( 256. * 256. * 256., 256. * 256., 256. );",
    "const vec4 UnpackFactors = UnpackDownscale / vec4( PackFactors, 1. );",
    "float unpackDepth( const in vec4 rgba ) {",
    "    return dot( rgba, UnpackFactors );",
    "}",
    "float linearizeDepth( const in float depth ) {",
    "    if ( orthographic > 0.5 ) return mix( near, far, depth );",
    "    float z = depth * 2.0 - 1.0;",
    "    return ( 2.0 * near * far ) / ( far + near - z * ( far - near ) );",
    "}",
    "float blurAmount( const in float linearDepth ) {",
    "    float halfWidth = focusAreaWidth * max( focusDistance, 1.0 ) / max( resolution.x, 1.0 );",
    "    float dist = linearDepth - focusDistance;",
    "    float over = max( abs( dist ) - halfWidth, 0.0 );",
    "    float level = dist < 0.0 ? nearBlurLevel : farBlurLevel;",
    "    return clamp( over / max( focusDistance, 1.0 ) / 4.0 * level, 0.0, 1.0 );",
    "}",
    "void main() {",
    "    vec2 uv = vUvScaled;",
    "    vec2 texel = 1.0 / max( resolution, vec2( 1.0 ) );",
    "    vec4 centerColor = texture2D( tColor, uv );",
    "    float centerLinear = linearizeDepth( unpackDepth( texture2D( tDepth, uv ) ) );",
    "    float centerBlur = blurAmount( centerLinear );",
    "    float maxRadius = centerBlur * aperture * 0.02 * min( resolution.x, resolution.y );",
    "    maxRadius = min( maxRadius, min( resolution.x, resolution.y ) * 0.05 );",
    "    if ( maxRadius < 0.5 || centerColor.a < 0.02 ) {",
    "        gl_FragColor = centerColor;",
    "        return;",
    "    }",
    "    vec3 accum = centerColor.rgb * centerColor.a;",
    "    float totalWeight = centerColor.a;",
    "    const int SAMPLES = 32;",
    "    for ( int i = 1; i < SAMPLES; i ++ ) {",
    "        float fi = float( i );",
    "        float radius = sqrt( ( fi + 0.5 ) / float( SAMPLES ) );",
    "        float angle = fi * 2.399963229728653;",
    "        vec2 offset = vec2( cos( angle ), sin( angle ) ) * radius * maxRadius * texel;",
    "        vec2 sampleUV = clamp( uv + offset, vec2( 0.0 ), vec2( 1.0 ) );",
    "        vec4 sampleColor = texture2D( tColor, sampleUV );",
    "        accum += sampleColor.rgb * sampleColor.a;",
    "        totalWeight += sampleColor.a;",
    "    }",
    "    float coverage = totalWeight / float( SAMPLES );",
    "    vec3 sharp = accum / max( totalWeight, 0.0001 );",
    "    gl_FragColor = vec4( sharp, coverage );",
    "}",
  ].join("\n");

  function createSceneDofClass(THREE) {
    function SceneDof() {
      this.enabled = false;
      this.depthMaterial = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking });
      this.material = new THREE.ShaderMaterial({
        uniforms: {
          tColor: { type: "t", value: null },
          tDepth: { type: "t", value: null },
          resolution: { type: "v2", value: new THREE.Vector2(1, 1) },
          uvScale: { type: "v2", value: new THREE.Vector2(1, 1) },
          orthographic: { type: "f", value: 0 },
          near: { type: "f", value: 0.1 },
          far: { type: "f", value: 5000 },
          aperture: { type: "f", value: 0 },
          focusDistance: { type: "f", value: 80 },
          focusAreaWidth: { type: "f", value: 0 },
          nearBlurLevel: { type: "f", value: 1 },
          farBlurLevel: { type: "f", value: 1 },
        },
        vertexShader: VERTEX_SHADER,
        fragmentShader: FRAGMENT_SHADER,
      });
      this.material.transparent = false;
      this.material.depthTest = false;
      this.material.depthWrite = false;
      this.scene = new THREE.Scene();
      this.camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
      this.scene.add(this.camera);
      this.quad = new THREE.Mesh(new THREE.PlaneBufferGeometry(2, 2), this.material);
      this.scene.add(this.quad);
      this.colorTarget = null;
      this.depthTarget = null;
    }

    SceneDof.prototype.configure = function (settings) {
      const u = this.material.uniforms;
      u.orthographic.value = settings.orthographic ? 1 : 0;
      u.near.value = settings.near;
      u.far.value = settings.far;
      u.aperture.value = settings.aperture;
      u.focusDistance.value = settings.focusDistance;
      u.focusAreaWidth.value = settings.focusAreaWidth;
      u.nearBlurLevel.value = settings.nearBlurLevel;
      u.farBlurLevel.value = settings.farBlurLevel;
    };

    SceneDof.prototype.setSize = function (width, height) {
      if (this.colorTarget && this.colorTarget.width === width && this.colorTarget.height === height) return;
      if (this.colorTarget) this.colorTarget.dispose();
      if (this.depthTarget) this.depthTarget.dispose();
      this.colorTarget = new THREE.WebGLRenderTarget(width, height, {
        minFilter: THREE.LinearFilter,
        magFilter: THREE.LinearFilter,
        format: THREE.RGBAFormat,
      });
      this.depthTarget = new THREE.WebGLRenderTarget(width, height, {
        minFilter: THREE.NearestFilter,
        magFilter: THREE.NearestFilter,
        format: THREE.RGBAFormat,
      });
    };

    // renderer: WebGL renderer; target: the pass output target; scene/camera:
    // the RenderPass inputs; viewport: target viewport; forceClear: as in
    // THREE.RenderPass.
    SceneDof.prototype.render = function (renderer, target, scene, camera, viewport, forceClear) {
      this.setSize(target.width, target.height);
      this.colorTarget.viewport.copy(viewport);
      this.depthTarget.viewport.copy(viewport);
      const previous = scene.overrideMaterial;
      renderer.render(scene, camera, this.colorTarget, forceClear);
      const hidden = [];
      scene.traverse?.((node) => {
        if (node.__zoidiumOpticalFlareQuad) {
          hidden.push([node, node.visible]);
          node.visible = false;
        }
      });
      try {
        scene.overrideMaterial = this.depthMaterial;
        renderer.render(scene, camera, this.depthTarget, forceClear);
      } finally {
        scene.overrideMaterial = previous;
        for (const [node, visible] of hidden) node.visible = visible;
      }
      this.material.uniforms.tColor.value = this.colorTarget.texture;
      this.material.uniforms.tDepth.value = this.depthTarget.texture;
      this.material.uniforms.resolution.value.set(viewport.z, viewport.w);
      this.material.uniforms.uvScale.value.set(viewport.z / target.width, viewport.w / target.height);
      renderer.render(this.scene, this.camera, target, forceClear);
    };

    SceneDof.prototype.unload = function () {
      if (this.colorTarget) this.colorTarget.dispose();
      if (this.depthTarget) this.depthTarget.dispose();
      this.colorTarget = null;
      this.depthTarget = null;
      if (this.material) this.material.dispose();
      if (this.depthMaterial) this.depthMaterial.dispose();
      this.quad.geometry.dispose();
      this.enabled = false;
    };

    return SceneDof;
  }

  return { createSceneDofClass: createSceneDofClass };
})();

text./plugins/camera-plus/scene-motion-blur.j:
// Camera motion blur integrates fresh renders at fixed shutter offsets. No
// history of rendered frames is retained. Targets are reused only as scratch.
parts.motion = (function () {
  const MAX_SAMPLES = 8;

  function sampleOffsets(samples, shutter) {
    const count = Math.max(1, Math.min(MAX_SAMPLES, Math.round(Number(samples) || 1)));
    const width = Math.max(0, Math.min(2, Number(shutter) || 0));
    return Array.from({ length: count }, (_, i) => ((i + 0.5) / count - 0.5) * width);
  }

  function createSceneMotionBlurClass(THREE) {
    class SceneMotionBlur {
      constructor() {
        this.sampleTarget = null;
        this.accumTarget = null;
        const makePass = () => new THREE.ShaderPass(new THREE.ShaderMaterial({
          uniforms: THREE.UniformsUtils.clone(THREE.CopyShader.uniforms),
          vertexShader: THREE.CopyShader.vertexShader,
          fragmentShader: THREE.CopyShader.fragmentShader,
          depthTest: false,
          depthWrite: false,
        }));
        this.addPass = makePass();
        this.addPass.material.transparent = true;
        this.addPass.material.blending = THREE.CustomBlending;
        this.addPass.material.blendSrc = THREE.OneFactor;
        this.addPass.material.blendDst = THREE.OneFactor;
        this.addPass.material.blendEquation = THREE.AddEquation;
        this.copyPass = makePass();
      }
      setSize(target) {
        if (this.sampleTarget && this.sampleTarget.width === target.width && this.sampleTarget.height === target.height) return;
        if (this.sampleTarget) this.sampleTarget.dispose();
        if (this.accumTarget) this.accumTarget.dispose();
        this.sampleTarget = new THREE.WebGLRenderTarget(target.width, target.height, {
          format: THREE.RGBAFormat, minFilter: THREE.LinearFilter, magFilter: THREE.LinearFilter,
          depthBuffer: true, stencilBuffer: false,
        });
        this.accumTarget = new THREE.WebGLRenderTarget(target.width, target.height, {
          format: THREE.RGBAFormat, type: THREE.FloatType,
          minFilter: THREE.NearestFilter, magFilter: THREE.NearestFilter,
          depthBuffer: false, stencilBuffer: false,
        });
      }
      render(renderer, target, time, settings, evaluate, draw, forceClear) {
        this.setSize(target);
        this.sampleTarget.viewport.copy(target.viewport);
        this.accumTarget.viewport.copy(target.viewport);
        const offsets = sampleOffsets(settings.samples, settings.shutter);
        const color = renderer.getClearColor().clone();
        const alpha = renderer.getClearAlpha();
        try {
          renderer.setClearColor(0, 0);
          renderer.clearTarget(this.accumTarget, true, false, false);
          this.addPass.uniforms.opacity.value = 1 / offsets.length;
          for (const offset of offsets) {
            evaluate(time + offset);
            draw(this.sampleTarget, true);
            // Sample targets have the same physical size as the accumulation
            // target, even when the layer uses a smaller viewport.
            this.addPass.uniforms.uvScale?.value?.set(1, 1);
            this.addPass.render(renderer, this.accumTarget, this.sampleTarget, false);
          }
          this.copyPass.uniforms.uvScale?.value?.set(1, 1);
          this.copyPass.render(renderer, target, this.accumTarget, forceClear);
        } finally {
          try {
            evaluate(time);
          } finally {
            renderer.setClearColor(color, alpha);
          }
        }
      }
      unload() {
        if (this.sampleTarget) this.sampleTarget.dispose();
        if (this.accumTarget) this.accumTarget.dispose();
        this.sampleTarget = this.accumTarget = null;
